  System.out.println("PASS"+cases+" Source NPC tick-view original-constructors/origin/Ref/live/target/weak/identity/legacy contracts; constructors="+constructors+", rejected="+rejects+", original-Hub-roots="+roots+", encounter-waits="+waits+"; accepted receiver HP/IO/Main/PC-discovery/full Source remain open");
